{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2192-06-29 23:50:00",
      "speaker": "Doctor",
      "text": "Hi, I'm Dr. Lee. I understand you've been having abdominal pain, nausea, and vomiting. Can you tell me more about what’s been going on?"
    },
    {
      "turn_number": 2,
      "time": "2192-06-29 23:52:00",
      "speaker": "Patient",
      "text": "Yes, it’s been getting worse over the past week. The pain is mostly in my upper right side, and I’ve been vomiting a lot. I think it’s another partial bowel blockage."
    },
    {
      "turn_number": 3,
      "time": "2192-06-29 23:54:00",
      "speaker": "Doctor",
      "text": "That sounds familiar. Given your history of Crohn’s and multiple surgeries, that’s definitely possible. You came in with an NG tube already placed?"
    },
    {
      "turn_number": 4,
      "time": "2192-06-29 23:56:00",
      "speaker": "Patient",
      "text": "Yes, they put it in at the outside hospital. It helps a little, but the pain is still bad."
    },
    {
      "turn_number": 5,
      "time": "2192-06-29 23:58:00",
      "speaker": "Doctor",
      "text": "We’ll keep the NG tube for now to help with the vomiting. Your labs show your kidney function is a bit off—creatinine is elevated to 1.6, which is higher than your baseline."
    },
    {
      "turn_number": 6,
      "time": "2192-06-30 00:00:00",
      "speaker": "Patient",
      "text": "Oh, that’s not good. Is it from dehydration?"
    },
    {
      "turn_number": 7,
      "time": "2192-06-30 00:02:00",
      "speaker": "Doctor",
      "text": "Likely, especially with vomiting and not keeping fluids down. We’re giving IV fluids and also replaced some magnesium, which was low."
    },
    {
      "turn_number": 8,
      "time": "2192-06-30 00:04:00",
      "speaker": "Patient",
      "text": "Okay, that makes sense. What about pain control? I need something, but I know you’re cautious."
    },
    {
      "turn_number": 9,
      "time": "2192-06-30 00:06:00",
      "speaker": "Doctor",
      "text": "Yes, we are being careful. You’ve had issues in the past with sedation from Dilaudid, and our system flags that. We can give 1 mg IV every 3 hours if needed, but no more."
    },
    {
      "turn_number": 10,
      "time": "2192-06-30 00:08:00",
      "speaker": "Patient",
      "text": "I understand. I just want to be safe. I don’t want another Narcan incident like before."
    },
    {
      "turn_number": 11,
      "time": "2192-06-30 00:10:00",
      "speaker": "Doctor",
      "text": "Exactly. We’re monitoring closely. For now, we’ll stick to the plan and reassess your pain regularly."
    },
    {
      "turn_number": 12,
      "time": "2192-06-30 17:20:00",
      "speaker": "Doctor",
      "text": "Your blood culture came back — no growth, which is good. No sign of bloodstream infection."
    },
    {
      "turn_number": 13,
      "time": "2192-06-30 17:22:00",
      "speaker": "Patient",
      "text": "That’s a relief. I was worried about infection with everything going on."
    },
    {
      "turn_number": 14,
      "time": "2192-06-30 17:24:00",
      "speaker": "Doctor",
      "text": "We’ll keep an eye on it. Your urine culture showed mixed bacteria, but it looks like contamination, not a real UTI."
    },
    {
      "turn_number": 15,
      "time": "2192-06-30 17:26:00",
      "speaker": "Patient",
      "text": "Oh, okay. I thought maybe that could be causing the fever I had."
    },
    {
      "turn_number": 16,
      "time": "2192-06-30 17:28:00",
      "speaker": "Doctor",
      "text": "The fever might just be from the inflammation in your gut. We’re not seeing signs of active infection so far."
    },
    {
      "turn_number": 17,
      "time": "2192-07-01 08:00:00",
      "speaker": "Doctor",
      "text": "Good morning. How are you feeling today?"
    },
    {
      "turn_number": 18,
      "time": "2192-07-01 08:02:00",
      "speaker": "Patient",
      "text": "Still nauseous, but maybe a little less pain. The NG tube is uncomfortable."
    },
    {
      "turn_number": 19,
      "time": "2192-07-01 08:04:00",
      "speaker": "Doctor",
      "text": "I know it’s not comfortable, but it’s helping your stomach rest. We’ll keep it until we’re sure things are moving again."
    },
    {
      "turn_number": 20,
      "time": "2192-07-01 08:06:00",
      "speaker": "Patient",
      "text": "Okay. Any update on the imaging?"
    },
    {
      "turn_number": 21,
      "time": "2192-07-01 08:08:00",
      "speaker": "Doctor",
      "text": "Not yet. We’re planning a repeat abdominal X-ray tomorrow to see if the obstruction is improving."
    },
    {
      "turn_number": 22,
      "time": "2192-07-02 08:10:00",
      "speaker": "Doctor",
      "text": "We did a chest X-ray yesterday to check your NG tube placement. It’s in the right spot, in the stomach."
    },
    {
      "turn_number": 23,
      "time": "2192-07-02 08:12:00",
      "speaker": "Patient",
      "text": "That’s good. Is everything else okay?"
    },
    {
      "turn_number": 24,
      "time": "2192-07-02 08:14:00",
      "speaker": "Doctor",
      "text": "There was a new finding — a small area of consolidation in your right upper lung, possibly early pneumonia."
    },
    {
      "turn_number": 25,
      "time": "2192-07-02 08:16:00",
      "speaker": "Patient",
      "text": "Pneumonia? I haven’t had a cough or fever lately."
    },
    {
      "turn_number": 26,
      "time": "2192-07-02 08:18:00",
      "speaker": "Doctor",
      "text": "Sometimes it shows up on X-ray before symptoms. We’ll monitor you closely. No antibiotics yet unless you develop symptoms."
    },
    {
      "turn_number": 27,
      "time": "2192-07-02 08:20:00",
      "speaker": "Patient",
      "text": "Okay, just keep me posted."
    },
    {
      "turn_number": 28,
      "time": "2192-07-03 09:18:00",
      "speaker": "Doctor",
      "text": "Great news — your repeat abdominal X-ray shows the bowel dilation is gone. No signs of obstruction anymore."
    },
    {
      "turn_number": 29,
      "time": "2192-07-03 09:20:00",
      "speaker": "Patient",
      "text": "Really? That’s amazing! Does that mean I can eat soon?"
    },
    {
      "turn_number": 30,
      "time": "2192-07-03 09:22:00",
      "speaker": "Doctor",
      "text": "We’ll start with small sips of water today. If you tolerate that, we can slowly advance your diet."
    },
    {
      "turn_number": 31,
      "time": "2192-07-03 09:24:00",
      "speaker": "Patient",
      "text": "And can we take out the NG tube?"
    },
    {
      "turn_number": 32,
      "time": "2192-07-03 09:26:00",
      "speaker": "Doctor",
      "text": "If you do well with liquids, we can remove it tomorrow."
    },
    {
      "turn_number": 33,
      "time": "2192-07-03 14:00:00",
      "speaker": "Doctor",
      "text": "You’re doing well with sips. No nausea or vomiting. We’re going to try clear liquids now."
    },
    {
      "turn_number": 34,
      "time": "2192-07-03 14:02:00",
      "speaker": "Patient",
      "text": "That’s great. I’m so ready to eat something real."
    },
    {
      "turn_number": 35,
      "time": "2192-07-03 14:04:00",
      "speaker": "Doctor",
      "text": "One step at a time. We also got your second blood culture back — still no growth. That’s reassuring."
    },
    {
      "turn_number": 36,
      "time": "2192-07-04 08:00:00",
      "speaker": "Doctor",
      "text": "Morning. You made it through the night with clear liquids. No issues?"
    },
    {
      "turn_number": 37,
      "time": "2192-07-04 08:02:00",
      "speaker": "Patient",
      "text": "No, I feel good. Can we take the NG tube out now?"
    },
    {
      "turn_number": 38,
      "time": "2192-07-04 08:04:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll remove it this morning. After that, we’ll try a soft diet and keep monitoring."
    },
    {
      "turn_number": 39,
      "time": "2192-07-04 08:06:00",
      "speaker": "Patient",
      "text": "Thank you. I’ve missed eating so much."
    },
    {
      "turn_number": 40,
      "time": "2192-07-04 12:00:00",
      "speaker": "Doctor",
      "text": "You’re tolerating the soft diet well. Your kidney function is also improving — creatinine is down to 1.1."
    },
    {
      "turn_number": 41,
      "time": "2192-07-04 12:02:00",
      "speaker": "Patient",
      "text": "That’s great. Does that mean I can go home soon?"
    },
    {
      "turn_number": 42,
      "time": "2192-07-04 12:04:00",
      "speaker": "Doctor",
      "text": "Possibly tomorrow. We want to make sure you’re stable on food and pain is controlled with oral meds."
    },
    {
      "turn_number": 43,
      "time": "2192-07-04 12:06:00",
      "speaker": "Patient",
      "text": "I’ve been using the IV Dilaudid. Will I switch to pills?"
    },
    {
      "turn_number": 44,
      "time": "2192-07-04 12:08:00",
      "speaker": "Doctor",
      "text": "Yes, we’ll transition you to oral hydromorphone. Same strength, but safer at home."
    },
    {
      "turn_number": 45,
      "time": "2192-07-04 16:00:00",
      "speaker": "Doctor",
      "text": "You’re doing really well. We’re planning to discharge you tomorrow afternoon if all goes well."
    },
    {
      "turn_number": 46,
      "time": "2192-07-04 16:02:00",
      "speaker": "Patient",
      "text": "That’s wonderful. What about follow-up?"
    },
    {
      "turn_number": 47,
      "time": "2192-07-04 16:04:00",
      "speaker": "Doctor",
      "text": "You’ll need to see your GI doctor soon. Also, we’ll schedule a pneumonia follow-up chest X-ray in a week."
    },
    {
      "turn_number": 48,
      "time": "2192-07-04 16:06:00",
      "speaker": "Patient",
      "text": "And my other meds — thyroid, blood pressure, depression?"
    },
    {
      "turn_number": 49,
      "time": "2192-07-04 16:08:00",
      "speaker": "Doctor",
      "text": "Yes, resume all your home medications. We’ll send prescriptions and instructions with you."
    },
    {
      "turn_number": 50,
      "time": "2192-07-05 09:00:00",
      "speaker": "Doctor",
      "text": "You’ve made it through the night with no issues. We’re clearing you for discharge."
    },
    {
      "turn_number": 51,
      "time": "2192-07-05 09:02:00",
      "speaker": "Patient",
      "text": "Thank you so much. I feel so much better."
    },
    {
      "turn_number": 52,
      "time": "2192-07-05 09:04:00",
      "speaker": "Doctor",
      "text": "We’ll give you a summary, prescriptions, and instructions. Call your doctor if pain returns or you can’t keep food down."
    },
    {
      "turn_number": 53,
      "time": "2192-07-05 09:06:00",
      "speaker": "Patient",
      "text": "I will. And thank you for being careful with the pain meds."
    },
    {
      "turn_number": 54,
      "time": "2192-07-05 09:08:00",
      "speaker": "Doctor",
      "text": "We want you safe and comfortable. Take care, and we’ll see you in follow-up if needed."
    },
    {
      "turn_number": 55,
      "time": "2192-07-05 10:00:00",
      "speaker": "Doctor",
      "text": "One last thing — we’re due for your flu shot. Would you like it before you leave?"
    },
    {
      "turn_number": 56,
      "time": "2192-07-05 10:02:00",
      "speaker": "Patient",
      "text": "Yes, I haven’t had it this year. Is it safe with everything?"
    },
    {
      "turn_number": 57,
      "time": "2192-07-05 10:04:00",
      "speaker": "Doctor",
      "text": "Yes, it’s recommended. No live virus. We’ll give it before you go."
    },
    {
      "turn_number": 58,
      "time": "2192-07-05 11:00:00",
      "speaker": "Doctor",
      "text": "Flu shot is in. All set for discharge."
    },
    {
      "turn_number": 59,
      "time": "2192-07-05 11:02:00",
      "speaker": "Patient",
      "text": "Perfect. I’m ready to go home."
    },
    {
      "turn_number": 60,
      "time": "2192-07-05 12:00:00",
      "speaker": "Doctor",
      "text": "Transport is scheduled for 1 PM. Nurse will go over meds and signs to watch for."
    },
    {
      "turn_number": 61,
      "time": "2192-07-05 12:02:00",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I really appreciate everything."
    },
    {
      "turn_number": 62,
      "time": "2192-07-05 12:04:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Take care of yourself and follow up as planned."
    },
    {
      "turn_number": 63,
      "time": "2192-07-05 13:00:00",
      "speaker": "Doctor",
      "text": "Just checking in before you leave. Any last questions?"
    },
    {
      "turn_number": 64,
      "time": "2192-07-05 13:02:00",
      "speaker": "Patient",
      "text": "No, I think I’ve got everything. Thanks again."
    },
    {
      "turn_number": 65,
      "time": "2192-07-05 14:00:00",
      "speaker": "Doctor",
      "text": "Safe travels home. We’ll see you in clinic if needed."
    },
    {
      "turn_number": 66,
      "time": "2192-07-05 14:02:00",
      "speaker": "Patient",
      "text": "I’ll be in touch if anything comes up."
    },
    {
      "turn_number": 67,
      "time": "2192-07-05 15:00:00",
      "speaker": "Doctor",
      "text": "Take care. You did great."
    }
  ],
  "summary": {
    "admission_start": "2192-06-29 23:50:00",
    "admission_end": "2192-07-05 16:09:00",
    "summary_paragraph": "A woman with a history of Crohn’s disease and multiple bowel resections was admitted for abdominal pain, nausea, and vomiting concerning for partial small bowel obstruction. She presented with an NG tube in place from an outside hospital and elevated creatinine, likely due to dehydration. Imaging initially supported obstruction, but a follow-up abdominal X-ray on hospital day 4 showed resolution of bowel dilation. She was managed conservatively with bowel rest, IV fluids, and cautious pain control using IV Dilaudid within safe limits. A chest X-ray revealed a new right upper lobe consolidation suggestive of early pneumonia, though she remained asymptomatic and did not require antibiotics. She transitioned successfully to oral intake, had her NG tube removed, and was discharged on oral hydromorphone with plans for follow-up on pneumonia and GI issues. A flu vaccine was administered prior to discharge.",
    "problems": [
      "Other intestinal obstruction",
      "Crohn's disease, unspecified, without complications",
      "Other postprocedural complications and disorders of digestive system",
      "Postsurgical malabsorption, not elsewhere classified",
      "Opioid dependence, uncomplicated",
      "Major depressive disorder, single episode, unspecified",
      "Hypothyroidism, unspecified",
      "Essential (primary) hypertension",
      "Other chronic pain",
      "Anxiety disorder, unspecified",
      "Post-traumatic stress disorder, unspecified",
      "Acquired absence of other specified parts of digestive tract",
      "Gastro-esophageal reflux disease without esophagitis",
      "Fever, unspecified",
      "Long term (current) use of antithrombotics/antiplatelets"
    ]
  }
}
